INSERT INTO collection_pages VALUES('d755576ece455d7cb12a82aeebcb5191cf7b1b4514c428cc8703591c435f6c03','eae9b976b25abfd416ffa4bedbd394fe825c7be4e45ebdfbe401941e627e19a8','{"hasNext":false,"items":[{"author":{"account":{"login":"malikhisyam","providerType":"User"},"email":"hisyamabdulmalik04@gmail.com","name":"Malik Hisyam"},"authoredDate":"2026-07-27T08:56:07Z","committedDate":"2026-07-27T08:56:07Z","committer":{"account":{"login":"malikhisyam","providerType":"User"},"email":"hisyamabdulmalik04@gmail.com","name":"Malik Hisyam"},"observedAt":"2026-10-08T23:56:18.384Z","repositoryId":1313599163,"sha":"84913635b187c026afdb8a6689bc8da5c319c912"},{"author":{"account":{"login":"malikhisyam","providerType":"User"},"email":"hisyamabdulmalik04@gmail.com","name":"Malik Hisyam"},"authoredDate":"2026-07-27T08:40:37Z","committedDate":"2026-07-27T08:40:37Z","committer":{"account":{"login":"malikhisyam","providerType":"User"},"email":"hisyamabdulmalik04@gmail.com","name":"Malik Hisyam"},"observedAt":"2026-10-08T23:56:18.384Z","repositoryId":1313599163,"sha":"8b2bf270126222c9bd1a89650e34e1e73ac73e38"}],"observedAt":"2026-10-08T23:56:18.384Z","raw":[{"author":{"avatar_url":"https://avatars.githubusercontent.com/u/76864212?v=4","events_url":"https://api.github.com/users/malikhisyam/events{/privacy}","followers_url":"https://api.github.com/users/malikhisyam/followers","following_url":"https://api.github.com/users/malikhisyam/following{/other_user}","gists_url":"https://api.github.com/users/malikhisyam/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/malikhisyam","id":76864212,"login":"malikhisyam","node_id":"MDQ6VXNlcjc2ODY0MjEy","organizations_url":"https://api.github.com/users/malikhisyam/orgs","received_events_url":"https://api.github.com/users/malikhisyam/received_events","repos_url":"https://api.github.com/users/malikhisyam/repos","site_admin":false,"starred_url":"https://api.github.com/users/malikhisyam/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/malikhisyam/subscriptions","type":"User","url":"https://api.github.com/users/malikhisyam","user_view_type":"public"},"comments_url":"https://api.github.com/repos/malikhisyam/sf-setup-for-agent/commits/84913635b187c026afdb8a6689bc8da5c319c912/comments","commit":{"author":{"date":"2026-07-27T08:56:07Z","email":"hisyamabdulmalik04@gmail.com","name":"Malik Hisyam"},"comment_count":0,"committer":{"date":"2026-07-27T08:56:07Z","email":"hisyamabdulmalik04@gmail.com","name":"Malik Hisyam"},"message":"Fix: _accdsn.sfc and .sfkey are generated, not obtained from a DBA\n\nThe skill told agents to collect _accdsn.sfc and the .sfkey pair up front,\nwhich made them block on a human for files the app produces itself. The core\ngeneratedsn.cfm reads `select codename, shdata from teodcompanyreg` on the\nmaster registry, writes .../config/_accdsn.sfc and .../ssh/{private,public}.sfkey\nvia genDSNFile, then calls setDatasource — one URL does all of it. That is also\nwhy those paths are gitignored.\n\nThe real human dependency is upstream: the account must be registered/migrated\nfor local development on the registry, which is the DBA request. Reworded the\ncredential checklist, backend §4/§6, troubleshooting, the accdsn template header\nand the architecture doc; preflight now WARNs with the generator URL instead of\nFAILing with \"ask the DBA\".\n\nCo-Authored-By: Claude Opus 5 <noreply@anthropic.com>","tree":{"sha":"a8c2deace42d165b68b50e3b184db8f993408685","url":"https://api.github.com/repos/malikhisyam/sf-setup-for-agent/git/trees/a8c2deace42d165b68b50e3b184db8f993408685"},"url":"https://api.github.com/repos/malikhisyam/sf-setup-for-agent/git/commits/84913635b187c026afdb8a6689bc8da5c319c912","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":{"avatar_url":"https://avatars.githubusercontent.com/u/76864212?v=4","events_url":"https://api.github.com/users/malikhisyam/events{/privacy}","followers_url":"http